# Lesson 3.9: links (a, href, target) and clickable images
L = lambda *a: '\n'.join(a)
def P(title, story, code, dis): return (title, story, code, dis)
P39 = [
 P('A link to Wikipedia', 'Write a heading that says Research and then a link whose clickable words are Wikipedia and that goes to https://www.wikipedia.org.',
   L('<h1>Research</h1>', '<a href="https://www.wikipedia.org">Wikipedia</a>'),
   [(1, '<a href="https://www.wikipedia.org">Wikipedia'), (1, '<a href="www.wikipedia.org">Wikipedia</a>'), (1, '<a href="https://www.wikipedia.org">Wikipedia</h1>')]),
 P('Open in a new tab', 'Write a link that goes to https://www.youtube.com with the clickable words Watch videos. It leaves your site, so it must open in a new tab with target.',
   L('<a href="https://www.youtube.com" target="_blank">Watch videos</a>', '<p>Come back soon.</p>'),
   [(0, '<a href="https://www.youtube.com" target="blank">Watch videos</a>'), (0, '<a href="https://www.youtube.com" target="_blank">Watch videos<a>'), (0, '<a href="https://www.youtube.com" target=_blank>Watch videos</a>')]),
 P('A link inside a sentence', 'Write a paragraph that says Read about dolphins today. Make only the word dolphins a link to https://www.nationalgeographic.com.',
   L('<p>Read about <a href="https://www.nationalgeographic.com">dolphins</a> today.</p>'),
   [(0, '<p>Read about <a href="https://www.nationalgeographic.com">dolphins</p></a> today.'), (0, '<p>Read about dolphins <a href="https://www.nationalgeographic.com">today</a>.</p>'), (0, '<p>Read about <a href="https://www.nationalgeographic.com">dolphins</a today.</p>')]),
 P('A bold link', 'Write a paragraph with the bold word NASA that is also a link to https://www.nasa.gov. The strong tag goes inside the link.',
   L('<p><a href="https://www.nasa.gov"><strong>NASA</strong></a></p>'),
   [(0, '<p><a href="https://www.nasa.gov"><strong>NASA</a></strong></p>'), (0, '<p><a href="https://www.nasa.gov"><strong>NASA</strong></p></a>'), (0, '<p><strong>NASA</strong></p>')]),
 P('A heading that is a link', 'Make the whole heading Menu a link to https://www.chick-fil-a.com. Put the link inside the heading tags.',
   L('<h2>', '<a href="https://www.chick-fil-a.com">Menu</a>', '</h2>'),
   [(1, '<a href="https://www.chick-fil-a.com">Menu</h2>'), (1, '<a href="https://www.chick-fil-a.com" target="blank">Menu</a>'), (2, '</h1>')]),
 P('Two links in two paragraphs', 'Write two paragraphs. The first has a link to https://www.espn.com with the words Sports news that opens in a new tab. The second has a link to the page contact.html (it stays in the same tab) with the words Contact us.',
   L('<p><a href="https://www.espn.com" target="_blank">Sports news</a></p>', '<p><a href="contact.html">Contact us</a></p>'),
   [(0, '<p><a href="https://www.espn.com" target="_blank">Sports news</p></a>'), (1, '<p><a href="contact.html" target="_blank">Contact us</a></p>'), (1, '<p><a href=contact.html>Contact us</a></p>')]),
 P('A clickable image', 'Make a picture that is a link. The picture is at https://images.example.org/rocket.png with the alt text A rocket launching, 200px wide. Clicking it goes to https://www.nasa.gov in a new tab. The image goes inside the link.',
   L('<a href="https://www.nasa.gov" target="_blank">', '<img src="https://images.example.org/rocket.png" alt="A rocket launching" style="width: 200px;">', '</a>'),
   [(2, '</a></a>'), (1, '<img src="https://images.example.org/rocket.png" alt="A rocket launching" style="width: 200px;"></img>'), (0, '<a href="https://www.nasa.gov" target="_blank"')]),
 P('A link with its own color', 'Write a paragraph that says Visit our shop. whose words Visit our shop are a link to https://www.etsy.com, colored teal with the color property on the link.',
   L('<p>', '<a href="https://www.etsy.com" style="color: teal;">Visit our shop</a>.', '</p>'),
   [(1, '<a href="https://www.etsy.com" style="colour: teal;">Visit our shop</a>.'), (1, '<a href="https://www.etsy.com" style="color: teal;">Visit our shop</a>'), (2, '</h1>')]),
 P('A full page with links', 'Build a full page titled Link Page. The body has a heading Link Page, a paragraph with a link to https://www.wikipedia.org (words: Wikipedia) that opens in a new tab, and a paragraph with a link to about.html (words: About me) in the same tab.',
   L('<!DOCTYPE html>', '<html>', '<head>', '<title>Link Page</title>', '</head>', '<body>', '<h1>Link Page</h1>', '<p><a href="https://www.wikipedia.org" target="_blank">Wikipedia</a></p>', '<p><a href="about.html">About me</a></p>', '</body>', '</html>'),
   [(7, '<p><a href="https://www.wikipedia.org" target="_blank">Wikipedia</p></a>'), (8, '<p><a href="about.html" target="_self_">About me</a></p>'), (6, '<h1>Link Page<h1>')]),
 P('A full page with a clickable image', 'Build a full page titled Space Fan. The body has a heading Space Fan, then a clickable picture: an image at https://images.example.org/moon.png with the alt text The moon at night, 300px wide, inside a link to https://www.nasa.gov that opens in a new tab. Then a paragraph that says Click the moon.',
   L('<!DOCTYPE html>', '<html>', '<head>', '<title>Space Fan</title>', '</head>', '<body>', '<h1>Space Fan</h1>', '<a href="https://www.nasa.gov" target="_blank">', '<img src="https://images.example.org/moon.png" alt="The moon at night" style="width: 300px;">', '</a>', '<p>Click the moon.</p>', '</body>', '</html>'),
   [(9, '</a></a>'), (8, '<img src="https://images.example.org/moon.png" style="width: 300px;">'), (7, '<a href="www.nasa.gov" target="_blank">')]),
]
T39 = [
 L('<h1>Research</h1>', '<a href="https://www.wikipedia.org">Wikipedia</a>'),
 L('<a href="https://www.youtube.com" target="_blank">Watch videos</a>', '<p>Come back soon.</p>'),
 L('<p>Read about <a href="https://www.nationalgeographic.com">dolphins</a> today.</p>', '<p>Then rest.</p>'),
 L('<p><a href="contact.html">Contact us</a></p>', '<p><a href="https://www.espn.com" target="_blank">Sports news</a></p>'),
 L('<h2>', '<a href="https://www.chick-fil-a.com" target="_blank">Menu</a>', '</h2>', '<p>Tap it.</p>'),
 L('<body style="text-transform: uppercase;">', '<p><a href="https://www.nasa.gov">space news</a></p>', '</body>'),
 L('<a href="https://www.nasa.gov" target="_blank">', '<img src="https://images.example.org/rocket.png" alt="A rocket launching" style="width: 200px;">', '</a>', '<p>Click the rocket.</p>'),
 L('<p style="text-align: center;">', '<a href="https://www.etsy.com" style="color: teal;">Visit our shop</a>', '</p>', '<p>Open daily.</p>'),
 L('<!DOCTYPE html>', '<html>', '<head>', '<title>Link Page</title>', '</head>', '<body>', '<h1>Link Page</h1>', '<p><a href="https://www.wikipedia.org" target="_blank">Wikipedia</a></p>', '<p><a href="about.html">About me</a></p>', '</body>', '</html>'),
 L('<!DOCTYPE html>', '<html>', '<head>', '<title>Mixed Links</title>', '</head>', '<body style="color: darkgreen;">', '<h1 style="font-size: 36px;">Mixed Links</h1>', '<p>Visit <a href="https://www.wikipedia.org" target="_blank"><strong>Wikipedia</strong></a> or <a href="notes.html">my notes</a>.</p>', '<a href="https://www.nasa.gov" target="_blank">', '<img src="https://images.example.org/moon.png" alt="The moon at night" style="width: 150px;">', '</a>', '</body>', '</html>'),
]
